WITH RecentProducts AS (SELECT *, SORT_ARRAY(tags) AS sorted_tags FROM products WHERE supplier_id = 39 AND (category = 'Books' OR product_name LIKE 'De%')), products_stats AS (SELECT CASE WHEN stock_qty >= 406 THEN 'high' WHEN stock_qty >= 160 THEN 'mid' ELSE 'low' END AS stock_qty_bucket, DATE_TRUNC('MONTH', launch_date) AS launch_month, SUM(CASE WHEN category = 'Home' THEN stock_qty ELSE 0 END) AS home_stock_qty FROM RecentProducts GROUP BY CASE WHEN stock_qty >= 406 THEN 'high' WHEN stock_qty >= 160 THEN 'mid' ELSE 'low' END, DATE_TRUNC('MONTH', launch_date)) SELECT * FROM products_stats WHERE home_stock_qty >= 68 ORDER BY launch_month DESC
